import math

def sum_geometric_series(a, n):
    # Calculates P_{n-1}(a, 1) = 1 + a + a^2 + ... + a^{n-1}
    # For n=4, we calculate 1 + a + a^2 + a^3
    s = 0
    for i in range(n):
        s += a**i
    return s

# Check for n=4 (requires sum up to degree 3)
n = 4
values = []
# Test a from 2 up to 10 to get a good GCD estimate
for a in range(2, 11):
    values.append(sum_geometric_series(a, n))

print(f"Values of 1+a+a^2+a^3 for a=2 to 10: {values}")

# Calculate GCD of these values
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if values:
    current_gcd = values[0]
    for i in range(1, len(values)):
        current_gcd = gcd(current_gcd, values[i])
    print(f"GCD of these values (c must divide this): {current_gcd}")

